// ═══ INTERNAL STRUCTURE ═══
// Node[] table — the bucket array
// Each bucket: null, or Node (linked list), or TreeNode (Red-Black tree)

static class Node<K,V> {
    final int hash;      // cached hash of key
    final K key;
    V value;
    Node<K,V> next;      // linked list pointer (collision chain)
}

// ═══ PUT OPERATION — step by step ═══
public V put(K key, V value) {
    // Step 1: Hash the key
    int hash = (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);
    // XOR high 16 bits with low 16 bits — spreads hash to avoid collisions
    // when table size is small (e.g., 16 buckets uses only bottom 4 bits)

    // Step 2: Find bucket index
    int index = hash & (table.length - 1);  // same as hash % capacity but faster!
    // capacity is always power of 2 → (n-1) is bitmask

    // Step 3: Check bucket
    // If empty → create new Node, place in bucket
    // If occupied → walk linked list:
    //   If same key found (hash equal AND key.equals()) → replace value
    //   If no match → append to end of list
    //   If list length ≥ 8 AND table.length ≥ 64 → TREEIFY (convert to Red-Black tree)

    // Step 4: Check load factor
    if (++size > capacity * loadFactor) resize();  // double + rehash all
}

// ═══ GET OPERATION ═══
public V get(Object key) {
    int hash = hash(key);
    int index = hash & (table.length - 1);
    Node<K,V> node = table[index];
    // If null → return null (key not present)
    // If linked list → walk: compare hash AND equals() for each node → O(n)
    // If tree → tree search: compare hash AND compareTo/equals → O(log n)
}

// ═══ RESIZE (rehash) ═══
// Triggered when: size > capacity * loadFactor (default: 12 = 16 * 0.75)
// New capacity = old * 2 (always power of 2)
// Every entry rehashed: new index = hash & (newCapacity - 1)
// Some entries MOVE to new position, some STAY (Java 8 optimization:
// each entry either stays at index or moves to index + oldCapacity)

// ═══ TREEIFICATION (Java 8+) ═══
// Before Java 8: bucket = linked list only → O(n) worst case for get()
// Java 8+: when bucket list ≥ 8 nodes AND table ≥ 64 buckets:
//   linked list → Red-Black tree → O(log n) lookup!
// When tree shrinks to ≤ 6 nodes: tree → linked list (UNTREEIFY_THRESHOLD = 6)
// WHY 8? Poisson distribution: probability of 8+ collisions in a bucket
// with good hash is ~0.00000006 — extremely rare. Tree is just a safety net.

// ═══ DEFAULT VALUES ═══
// Initial capacity: 16
// Load factor: 0.75 (good balance between space and time)
// Treeify threshold: 8 (linked list → tree)
// Untreeify threshold: 6 (tree → linked list)
// Min treeify capacity: 64 (table must be this big before treeifying)
```

