// ─── File: src/test/java/com/bank/hashmap/HashMapInternalsTest.java ───
package com.bank.hashmap;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class HashMapInternalsTest {

    // Helper: get internal table capacity
    private int getCapacity(HashMap<?,?> map) throws Exception {
        Field table = HashMap.class.getDeclaredField("table");
        table.setAccessible(true);
        Object[] arr = (Object[]) table.get(map);
        return arr == null ? 0 : arr.length;
    }

    // ═══ Default capacity: 16 ═══
    @Test
    void defaultCapacity_16() throws Exception {
        HashMap<String, String> map = new HashMap<>();
        map.put("SAV2001", "Rajesh");  // triggers table creation
        assertThat(getCapacity(map)).isEqualTo(16);
    }

    // ═══ Resize at load factor 0.75 ═══
    @Test
    void resize_atLoadFactor() throws Exception {
        HashMap<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < 12; i++) map.put(i, i);  // 12 = 16 * 0.75
        assertThat(getCapacity(map)).isEqualTo(16);    // still 16

        map.put(12, 12);  // 13th entry → exceeds threshold → RESIZE!
        assertThat(getCapacity(map)).isEqualTo(32);    // doubled to 32!
    }

    // ═══ Custom initial capacity ═══
    @Test
    void customCapacity() throws Exception {
        HashMap<String, String> map = new HashMap<>(100);
        map.put("key", "value");
        // Capacity rounds UP to nearest power of 2:
        assertThat(getCapacity(map)).isEqualTo(128);  // 100 → 128!
    }

    // ═══ Hash collision — same bucket ═══
    @Test
    void hashCollision_sameBucket() {
        // Keys with same hashCode → same bucket → linked list
        Map<BadHashKey, String> map = new HashMap<>();
        for (int i = 0; i < 10; i++) {
            map.put(new BadHashKey(i), "val-" + i);
        }
        // All 10 entries in ONE bucket (linked list or tree)
        assertThat(map).hasSize(10);
        assertThat(map.get(new BadHashKey(5))).isEqualTo("val-5");
    }

    // Key with intentionally bad hashCode (all same hash)
    static class BadHashKey {
        final int id;
        BadHashKey(int id) { this.id = id; }
        @Override public int hashCode() { return 42; }  // ALL same hash!
        @Override public boolean equals(Object o) {
            return o instanceof BadHashKey b && b.id == this.id;
        }
    }

    // ═══ Treeification at 8+ nodes ═══
    @Test
    void treeify_at8Nodes() {
        // When 8+ entries collide in one bucket AND table ≥ 64:
        // linked list → Red-Black tree
        // get() changes from O(n) to O(log n)
        HashMap<BadHashKey, String> map = new HashMap<>(64);
        for (int i = 0; i < 20; i++) {
            map.put(new BadHashKey(i), "val-" + i);
        }
        // Bucket has 20 entries → treeified → get() is O(log 20) ≈ 4 comparisons
        assertThat(map.get(new BadHashKey(15))).isEqualTo("val-15");
    }

    // ═══ Good hashCode → even distribution ═══
    @Test
    void goodHashCode_evenDistribution() {
        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < 10000; i++) {
            map.put("ACC-" + i, i);  // String.hashCode() distributes well
        }
        assertThat(map.get("ACC-5000")).isEqualTo(5000);  // O(1) average!
    }
}
